head.script:
// 상장관련공통함수
scwin.gWorkDD;
scwin.userParam;
scwin.testDateSet;
scwin.svrGubun = js_svrGubun; // DR전환시
scwin.gDepCd;
scwin.gEmpNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 오늘날짜로 초기화시킨다.
        const today = $c.ut.cGetToday("yyyymmdd");
        edt_BASE_DD.setValue(today);
        rdo_TERM.setValue(Number(Number(today.substring(4, 6)) % 3 - 1));
        if (rdo_TERM.getValue() < 1) {
            rdo_TERM.setValue('2');
        }
        if (scwin.svrGubun === "dr") {
            // DR일 경우 2011.01.28
            await $c.win.alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
            txb_TR_STATE_CD.setValue("-");
        } else {
            scwin.setTrstatcd();
        }
        await scwin.setCode();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        Grd_com_isur.style.zIndex = 30;

        // round처리
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35403.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        img_search.setDisabled(false);
        img_search.src = "../img/btn_select.gif";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35403.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_TR_STATE_CD_OnLoadError
 * @description dts_TR_STATE_CD 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_TR_STATE_CD_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_TR_STATE_CD);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35403.dts_TR_STATE_CD_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        // alert_error(dts_List);
        await $c.win.alert("해당 일자의 데이터가 존재하지 않습니다.");
        img_search.setDisabled(false);
        img_search.src = "../img/btn_select.gif";
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35403.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_WorkDD_OnLoadError
 * @description dts_WorkDD 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
