};

/**
 * @method
 * @name img_toExcel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_toExcel_onclick = function() {
    try {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF35403.xml", SCREN_PROCS_TP_CD_07);
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            $c.data.downloadGridViewExcel(grd_List, {fileName: "보통주거래현황 -거래량요건 목록", type: "8"});
        } else {
            $c.data.downloadGridViewExcel(grd_List, {fileName: "종류주식거래현황 -거래량요건 목록", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35403.img_toExcel_onclick" });
    }
};

/**
 * @method
 * @name img_search_onclick
 * @description img_search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
