 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35403.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35403.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35403.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name btn_Print_onclick
 * @description 「인쇄」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Print_onclick = async function() {
    try {
        await scwin.print();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35403.btn_Print_onclick" });
    }
};

/**
 * @method
 * @name dts_DEP_CD_1_OnLoadCompleted
 * @description dts_DEP_CD_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DEP_CD_1_OnLoadCompleted = function(rowcount) {
    try {
        // setObjectValue(cmb_DEP_CD_1, js_dep_cd) ;
        cmb_DEP_CD_1.setValue('');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35403.dts_DEP_CD_1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_1_OnLoadCompleted
 * @description dts_EMP_NO_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_1_OnLoadCompleted = function(rowcount) {
    try {
        // setObjectValue(cmb_EMP_NO_1, js_emp_no) ;
        cmb_EMP_NO_1.setValue('');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35403.dts_EMP_NO_1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_1_onselchange
 * @description cmb_DEP_CD_1 onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_1_onselchange = function() {
    try {
        scwin.gDepCd = cmb_DEP_CD_1.getValue();
        if (scwin.gDepCd === '') {
            cmb_EMP_NO_1.setValue('');
        }
        dts_EMP_NO_1.UseFilter = true;
        dts_EMP_NO_1.Filter();
        dts_EMP_NO_1.sort("DEP_CD", 0);
        // dts_EMP_NO_1.sort(); // W-Craft 주석처리
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35403.cmb_DEP_CD_1_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_1_OnFilter
 * @description EMP NO 1 On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_1_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO_1.getCellData(row, "DEP_CD") === scwin.gDepCd || dts_EMP_NO_1.getCellData(row, "DEP_CD") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35403.dts_EMP_NO_1_OnFilter" });
    }
};

/**
 * @method
 * @name grd_List_OnUserColor
 * @description grd List On User Color 처리
 * @param {Number} row 행 인덱스
 * @param {String} eventId eventId
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnUserColor = function(row, eventId) {
    try {
        if (eventId === "acolor25" && dts_List.getCellData(row, "ADMISU_EXMPT_RSN_CORR_YN") === 'Y') {
            return "#28A0FF";
        } else if (eventId === "acolor26" && dts_List.getCellData(row, "MGT_ISUR_DPND_AXTY_YN") === 'Y') {
            return "#E16A9D";
        }
        if (row % 2 === 0) return "#f2f5f9";

        else return "#ffffff";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35403.grd_List_OnUserColor" });
    }
};

/**
 * @method
 * @name grd_List2_OnUserColor
 * @description grd List2 On User Color 처리
 * @param {Number} row 행 인덱스
 * @param {String} eventId eventId
 * @returns {void}
 * @hidden N
 */
scwin.grd_List2_OnUserColor = function(row, eventId) {
    try {
        if (eventId === "acolor20" && dts_List.getCellData(row, "MGT_ISUR_DPND_AXTY_YN") === 'Y') {
            return "#E16A9D";
        }
        if (row % 2 === 0) return "#f2f5f9";

        else return "#ffffff";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35403.grd_List2_OnUserColor" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_DEP_CD_1",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_EMP_NO_1",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // setObjectValue(cmb_DEP_CD_1, js_dep_cd) ;
    // setObjectValue(cmb_EMP_NO_1, js_emp_no) ;
    cmb_DEP_CD_1.setValue('');
    cmb_EMP_NO_1.setValue('');
};

/**
 * @method
 * @name workDD
 * @description work DD 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.workDD = async function() {
    const sbmOptions = {
        id : "sbm_dts_WorkDD",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_WorkDD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.gWorkDD = dts_WorkDD.getCellData(1, "CALND_DD");
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setTrstatcd
 * @description set Trstatcd 처리
 * @returns {void}
 * @hidden N
 */
scwin.setTrstatcd = function() {
    txb_TR_STATE_CD.setValue($c.ud.fn_get_divtrstatcd(dts_TR_STATE_CD, edt_BASE_DD.getValue(), "2"));
    txb_ATS_STATE_CD.setValue($c.ud.fn_get_divtrstatcd(dts_TR_STATE_CD, edt_BASE_DD.getValue(), "3"));
};

/**
 * @method
 * @name listSync
 * @description 거래량 요건  검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (edt_BASE_DD.getValue() > $c.ut.cGetToday("yyyymmdd")) {
        await $c.win.alert("현재일자보다 기준일자가 이후일 수 없습니다.");
        edt_BASE_DD.focus();
        return;
    }
    if (rdo_TERM.getValue() < 1) {
        await $c.win.alert("기준월을 선택하세요.");
        rdo_TERM.focus();
        return;
    }
    img_search.setDisabled(true);
    img_search.src = "../img/btn_select_d.gif";
    if (scwin.svrGubun === "dr") {
        // DR일 경우 2011.01.28
        await $c.win.alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
        txb_TR_STATE_CD.setValue("-");
    } else {
        scwin.setTrstatcd();
    }
    await scwin.workDD();
    let url = "";
    if (MaxTab_01.getSelectedTabIndex() === 1) {
